package main
import (
    "database/sql"
    "fmt"
    _ "github.com/go-sql-driver/mysql"
)
func main() {
    db, err := sql.Open("mysql", "user:password@tcp(localhost:3306)/travel_info")
    if err != nil {
        panic(err.Error())
    }
    defer db.Close()
    var frenchName string
    err = db.QueryRow("SELECT french_name FROM landmarks WHERE english_name = ?", "Eiffel Tower").Scan(&frenchName)
    if err != nil {
        panic(err.Error())
    }
    fmt.Println("The French name of the Eiffel Tower is", frenchName)
}

