    [HttpTrigger(AuthorizationLevel.Function, "get", "post", Route = null)] HttpRequest req,
    ILogger log)
{
    log.LogInformation("C# HTTP trigger function processed a request.");
    // Retrieve the connection string and container name from app settings
    var connectionString = Environment.GetEnvironmentVariable("AzureWebJobsStorage");
    var containerName = Environment.GetEnvironmentVariable("ContainerName");
    // Create a blob client and get a reference to the container
    var blobClient = new BlobServiceClient(connectionString);
    var containerClient = blobClient.GetBlobContainerClient(containerName);
    // List all the blobs in the container
    var blobs = containerClient.GetBlobsAsync();
    // Process the blobs
    foreach (var blob in blobs)
    {
        log.LogInformation($"Processing blob: {blob.Name}");
        // Download the blob contents
        var blobClient = containerClient.GetBlobClient(blob.Name);
        var blobContents = await blobClient.DownloadAsync();
        // Perform some data processing on the contents
        var processedData = ProcessData(blobContents);
        // Upload the processed data to a new blob
        var newBlobName = $"{blob.Name}-processed";
        var newBlobClient = containerClient.GetBlobClient(newBlobName);
        await newBlobClient.UploadAsync(processedData);
    }
    return new OkResult();
}
