I apologize for the confusion, but the Go code you provided is for sentiment analysis and not for generating a WordNet graph. However, I can provide you with an example of how to use the WordNet package in Go to generate a WordNet graph for the words "Family" and "Home". 
Here is an example Go code:
```
package main
import (
	"fmt"
	"github.com/awalterschulze/gographviz"
	"github.com/awalterschulze/gographviz/ast"
	"github.com/awalterschulze/gographviz/parser"
	"github.com/awalterschulze/gographviz/types"
	"github.com/agnivade/levenshtein"
	"github.com/agnivade/levenshtein/search"
	"github.com/rainycape/dl"
	"github.com/rainycape/gonlp"
	"github.com/rainycape/gonlp/wordnet"
)
func main() {
	// Initialize the WordNet database
	wn, err := wordnet.New()
	if err != nil {
		panic(err)
	}
	// Get the synsets for the words "Family" and "Home"
	familySynsets, err := wn.Search("Family")
	if err != nil {
		panic(err)
	}
	homeSynsets, err := wn.Search("Home")
	if err != nil {
		panic(err)
	}
	// Create a new graph
	graphAst, err := parser.ParseString(`digraph {}`)
	if err != nil {
		panic(err)
	}
	graph := gographviz.NewGraph()
	if err := gographviz.Analyse(graphAst, graph); err != nil {
		panic(err)
	}
	// Add the synsets as nodes to the graph
	for _, synset := range familySynsets {
		nodeName := fmt.Sprintf("%s_%d", synset.Pos().String(), synset.Offset())
		node := &ast.NodeStmt{
			NodeType: ast.NodeType(types.NodeStmtTypeNode),
			Attrs: map[string]string{
				"label": fmt.Sprintf("%s (%s)", synset.Words()[0], synset.Pos().String()),
			},
			ID: nodeName,
		}
		graphAst.Stmts = append(graphAst.Stmts, node)
	}
	for _, synset := range homeSynsets {
		nodeName := fmt.Sprintf("%s_%d", synset.Pos().String(), synset.Offset())
		node := &ast.NodeStmt{
			NodeType: ast.NodeType(types.NodeStmtTypeNode),
			Attrs: map[string]string{
				"label": fmt.Sprintf("%s (%s)", synset.Words()[0], synset.Pos().String()),
			},
			ID: nodeName,
		}
		graphAst.Stmts = append(graphAst.Stmts, node)
	}
	// Add the lexical relationships as edges to the graph
	for _, familySynset := range familySynsets {
		for _, homeSynset := range homeSynsets {
			// Check for hypernymy relationship
			if familySynset.IsHypernym(homeSynset) {
				addEdge(graphAst, familySynset, homeSynset, "hypernym")
			}
			if homeSynset.IsHypernym(familySynset) {
				addEdge(graphAst, homeSynset, familySynset, "hypernym")
			}
			// Check for hyponymy relationship
			if familySynset.IsHyponym(homeSynset) {
				addEdge(graphAst, familySynset, homeSynset, "hyponym")
			}
			if homeSynset.IsHyponym(familySynset) {
				addEdge(graphAst, homeSynset, familySynset, "hyponym")
			}
			// Check for meronymy relationship
			if familySynset.IsMeronym(homeSynset) {
				addEdge(graphAst, familySynset, homeSynset, "meronym")
			}
			if homeSynset.IsMeronym(familySynset) {
				addEdge(graphAst, homeSynset, familySynset, "meronym")
			}
			// Check for holonymy relationship
			if familySynset.IsHolonym(homeSynset) {
				addEdge(graphAst, familySynset, homeSynset, "holonym")
			}
			if homeSynset.IsHolonym(familySynset) {
				addEdge(graphAst, homeSynset, familySynset, "holonym")
			}
			// Check for antonymy relationship
			for _, familyWord := range familySynset.Words() {
				for _, homeWord := range homeSynset.Words() {
					if levenshtein.Distance(familyWord, homeWord, search.Default) == 1 {
						addEdge(graphAst, familySynset, homeSynset, "antonym")
						addEdge(graphAst, homeSynset, familySynset, "antonym")
					}
				}
			}
		}
	}
	// Render the graph
	renderedGraph := gographviz.Render(graphAst, graph)
	fmt.Println(renderedGraph)
}
func addEdge(graphAst *ast.Graph, fromSynset, toSynset *wordnet.Synset, relationship string) {
	fromNodeName := fmt.Sprintf("%s_%d", fromSynset.Pos().String(), fromSynset.Offset())
	toNodeName := fmt.Sprintf("%s_%d", toSynset.Pos().String(), toSynset.Offset())
	edge := &ast.EdgeStmt{
		NodeType: ast.NodeType(types.NodeStmtTypeEdge),
		Attrs: map[string]string{
			"label": relationship,
		},
		From: fromNodeName,
		To:   toNodeName,
	}
	graphAst.Stmts = append(graphAst.Stmts, edge)
}
```
This code uses the `gonlp/wordnet` package to search for the synsets of the words "Family" and "Home". It then creates a new graph using the `gographviz` package and adds the synsets as nodes to the graph. It then checks for various lexical relationships between the synsets (hypernymy, hyponymy, meronymy, holonymy, and antonymy) and adds edges to the graph accordingly. Finally, it renders the graph as a string and prints it to the console.
Definitions:
- Hypernym: A word that represents a category or a generalization of a set of words.
- Hyponym: A word that is a specific member of a category or set of words represented by a hypernym.
- Meronym: A word that refers to a part of a whole.
- Holonym: A word that refers to the whole that a part belongs to.
- Antonym: A word that has the opposite meaning of another word.

