		function moveElement(element, finalX, finalY, interval) {
			var posX = parseInt(element.style.left);
			var posY = parseInt(element.style.top);
			if (posX === finalX && posY === finalY) {
				return;
			}
			if (posX < finalX) {
				posX++;
			} else if (posX > finalX) {
				posX--;
			}
			if (posY < finalY) {
				posY++;
			} else if (posY > finalY) {
				posY--;
			}
			element.style.left = posX + "px";
			element.style.top = posY + "px";
