Here's an example of how to implement a Trie data structure in Scala:
class TrieNode {
  var children = Map[Char, TrieNode]()
  var isEndOfWord = false
}
class Trie {
  var root = new TrieNode()
  def insert(word: String): Unit = {
    var node = root
    for (char <- word) {
      node.children += (char -> node.children.getOrElse(char, new TrieNode()))
      node = node.children(char)
    }
    node.isEndOfWord = true
  }
  def search(word: String): Boolean = {
    var node = root
    for (char <- word) {
      if (!node.children.contains(char)) {
        return false
      }
      node = node.children(char)
    }
    node.isEndOfWord
  }
}

