func sumOfPrimes() -> Int {
    var isPrime = [Bool](repeating: true, count: 101)
    isPrime[0] = false
    isPrime[1] = false

    for i in 2...Int(sqrt(100)) {
        if isPrime[i] {
            for j in stride(from: i*i, through: 100, by: i) {
                isPrime[j] = false
            }
        }
    }

    var sum = 0
    for i in 2...100 {
        if isPrime[i] {
            sum += i
        }
    }

    return sum
}
print(sumOfPrimes())
