```go
package main
import (
	"fmt"
	"strconv"
)
func main() {
	for i := 1; i <= 1000; i++ {
		if sumDigits(i) == i {
			square := i * i
			if sumDigits(square)/3 == i {
				fmt.Println(i)
			}
		}
	}
}
func sumDigits(n int) int {
	sum := 0
	for _, digit := range strconv.Itoa(n) {
		num, _ := strconv.Atoi(string(digit))
		sum += num
	}
	return sum
}
```

