                }
                used[i] = false;
            }
        }
        return false;
    }
    static bool CheckSum(int[] nums, int[] order) {
        int sum = order[0] + order[nums.Length - 1];
        for (int i = 1; i < nums.Length; i++) {
            sum += Math.Abs(order[i] - order[i - 1]);
        }
        return sum == nums.Sum();
    }
    static List<int> GetPrimes(int max) {
        List<int> primes = new List<int>();
        for (int i = 2; i <= max; i++) {
            bool isPrime = true;
            for (int j = 2; j <= Math.Sqrt(i); j++) {
                if (i % j == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.Add(i);
            }
        }
        return primes;
    }
}
```
